def transform(grid):
    from collections import Counter

    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find background color (most frequent)
    color_counts = Counter()
    for row in grid:
        for cell in row:
            color_counts[cell] += 1

    background = max(color_counts, key=color_counts.get)

    # Mark which background cells become 3
    becomes_3 = [[False] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != background:  # This is a pattern cell
                # Mark all 3x3 region background cells as 3
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
